package main
import "fmt"

func main() {
    var q int
    var soma, media float64
    fmt.Scan(&q)

    soldados := make([]float64, q)
    classificacao := make([]string, q)
    for i := 0; i < q; i++ {
        fmt.Scan(&soldados[i])
    }
    for _, valor := range soldados {
        soma+= valor
    }
     media = soma/float64(q)
    fmt.Printf("%.2f\n",media)

    for i := 0; i < q; i++ {
        if soldados[i] < media {
              classificacao[i] = "P"
        } else if soldados[i] > media {
            classificacao[i] = "G"
            } else {
                classificacao[i] = "M"
            }
    }

    for i := 0; i < q; i++ {
        fmt.Print(classificacao[i])
        if i < q-1 {
            fmt.Print(" ")
        }
    }
    fmt.Println()


}
